import{_ as a,o as d,c as e,a4 as r}from"./chunks/framework.BBs01uty.js";const b=JSON.parse('{"title":"分布式基础（CAP / 分布式事务 / 分布式 ID）","description":"","frontmatter":{},"headers":[],"relativePath":"service/distributed-basics.md","filePath":"service/distributed-basics.md"}'),s={name:"service/distributed-basics.md"};function o(n,t,i,l,h,p){return d(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="分布式基础-cap-分布式事务-分布式-id" tabindex="-1">分布式基础（CAP / 分布式事务 / 分布式 ID） <a class="header-anchor" href="#分布式基础-cap-分布式事务-分布式-id" aria-label="Permalink to &quot;分布式基础（CAP / 分布式事务 / 分布式 ID）&quot;">​</a></h1><blockquote><p><strong>优先级：P1（中高级岗必问）</strong> — 单机 → 分布式时才会遇到的问题。面试常考概念题：CAP、分布式事务方案、分布式 ID 方案。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">背景</p><p>你已有微前端、BFF、权限设计经验（分布式系统的应用层），本文补理论层：分布式为什么难、一致性怎么权衡、事务跨库怎么做。</p></div><h2 id="为什么分布式难" tabindex="-1">为什么分布式难 <a class="header-anchor" href="#为什么分布式难" aria-label="Permalink to &quot;为什么分布式难&quot;">​</a></h2><p>单机系统：事务、锁、一致性由数据库/OS 保证。多机后：</p><ul><li>一个事务跨多个库 → 没有全局事务管理器</li><li>一台机器挂 → 数据在哪？请求谁来接？</li><li>时钟不同步、网络可能延迟/丢包/分区</li></ul><p>核心矛盾：<strong>网络是不可靠的</strong>。所有分布式难题都源于此。</p><h2 id="cap-理论-必考" tabindex="-1">CAP 理论（必考） <a class="header-anchor" href="#cap-理论-必考" aria-label="Permalink to &quot;CAP 理论（必考）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字母</th><th>含义</th></tr></thead><tbody><tr><td>C（Consistency）</td><td>一致性：所有节点同时看到同一份数据</td></tr><tr><td>A（Availability）</td><td>可用性：任何请求都有响应</td></tr><tr><td>P（Partition tolerance）</td><td>分区容错：网络分区（节点失联）时系统仍工作</td></tr></tbody></table><p><strong>定理</strong>：网络分区必然发生（P 必选），所以只能在 C 和 A 之间二选一：</p><ul><li><strong>CP 系统</strong>：分区时拒绝服务保证一致（ZooKeeper、etcd、HBase）</li><li><strong>AP 系统</strong>：分区时继续服务，允许短暂不一致（Eureka、Cassandra、绝大多数业务系统）</li></ul><p><strong>业务系统的实际答案</strong>：平时一致，分区时选 A（可用性），通过<strong>最终一致性</strong>（消息队列、异步补偿）补 C。</p><p><strong>面试题</strong>：MySQL 主从是 CP 还是 AP？——AP + 最终一致：主从有延迟，从库可能读到旧数据，但最终同步。</p><h2 id="base-理论-cap-的落地方案" tabindex="-1">BASE 理论（CAP 的落地方案） <a class="header-anchor" href="#base-理论-cap-的落地方案" aria-label="Permalink to &quot;BASE 理论（CAP 的落地方案）&quot;">​</a></h2><ul><li><strong>Basically Available</strong>：基本可用（降级、限流也算）</li><li><strong>Soft state</strong>：软状态（允许中间状态，如&quot;支付中&quot;）</li><li><strong>Eventually consistent</strong>：最终一致（异步同步到一致）</li></ul><h2 id="分布式事务-必考-选一种讲透" tabindex="-1">分布式事务（必考，选一种讲透） <a class="header-anchor" href="#分布式事务-必考-选一种讲透" aria-label="Permalink to &quot;分布式事务（必考，选一种讲透）&quot;">​</a></h2><p>跨库/跨服务事务，常见方案：</p><table tabindex="0"><thead><tr><th>方案</th><th>思路</th><th>优缺点</th></tr></thead><tbody><tr><td><strong>2PC（两阶段提交）</strong></td><td>协调者先问所有参与者&quot;能提交吗&quot;（准备），全同意才提交（提交）</td><td>强一致但<strong>阻塞</strong>（协调者挂了全卡住）、性能差</td></tr><tr><td><strong>TCC</strong></td><td>Try（预留资源）→ Confirm（确认）→ Cancel（回滚），业务自己实现三方法</td><td>性能好，但<strong>业务侵入大</strong>（每个方法写三份逻辑）</td></tr><tr><td><strong>本地消息表</strong></td><td>事务内写业务 + 消息表同库提交；后台定时扫消息表发 MQ；消费者幂等</td><td>简单可靠，业界常用（RocketMQ 事务消息即此思想的封装）</td></tr><tr><td><strong>Saga</strong></td><td>长事务拆多个本地事务 + 补偿（逆操作）</td><td>无锁高性能，但<strong>无隔离性</strong>（中间状态可见）</td></tr></tbody></table><p><strong>面试建议</strong>：把<strong>本地消息表</strong>讲透（原理 + 代码结构），再提 TCC 是&quot;最终一致性场景的强一致性变体&quot;。别每个都讲一半。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本地消息表流程：</span></span>
<span class="line"><span>业务事务（订单库）: 写订单 + 写消息表（status=待发送） → 同库事务，要么都成要么都败</span></span>
<span class="line"><span>后台任务: 扫描待发送消息 → 发 MQ → 标记已发送</span></span>
<span class="line"><span>消费者: 消费 + 幂等（防止重复）</span></span></code></pre></div><h2 id="分布式-id-必考" tabindex="-1">分布式 ID（必考） <a class="header-anchor" href="#分布式-id-必考" aria-label="Permalink to &quot;分布式 ID（必考）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>原理</th><th>特点</th></tr></thead><tbody><tr><td>UUID</td><td>全局唯一字符串</td><td>无序、太长、影响索引性能</td></tr><tr><td>数据库自增</td><td>单点自增</td><td>简单但单点、性能低</td></tr><tr><td><strong>雪花算法（Snowflake）</strong></td><td>64 位：时间戳(41) + 机器 ID(10) + 序列号(12)</td><td><strong>业界主流</strong>：趋势递增、无依赖、高性能</td></tr><tr><td>Redis INCR</td><td>原子自增</td><td>依赖 Redis 可用性</td></tr></tbody></table><p><strong>雪花算法 64 位结构</strong>（面试画图）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0 | 41位时间戳（毫秒）| 10位机器ID | 12位序列号</span></span>
<span class="line"><span>符号位   ~69年（可自定纪元）    每毫秒4096个</span></span></code></pre></div><p><strong>注意</strong>：依赖机器时钟，时钟回拨会生成重复 ID（解决：回拨时等待/用备用机器号）。</p><h2 id="分布式理论其他高频点" tabindex="-1">分布式理论其他高频点 <a class="header-anchor" href="#分布式理论其他高频点" aria-label="Permalink to &quot;分布式理论其他高频点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>考点</th><th>要点</th></tr></thead><tbody><tr><td>一致性哈希</td><td>节点增减只影响少量 key 的映射（环 + 虚拟节点），用于缓存集群路由</td></tr><tr><td>脑裂</td><td>集群分区后出现两个&quot;主&quot;，解决：选举需要多数派（过半机制）</td></tr><tr><td>选举</td><td>Raft/Paxos：多数派同意才提交，ZooKeeper/etcd 都用</td></tr><tr><td>限流</td><td>计数器 / 滑动窗口 / 令牌桶（Guava RateLimiter）/ 漏桶</td></tr><tr><td>熔断降级</td><td>失败率超阈值熔断（Sentinel/Hystrix），见微服务篇</td></tr></tbody></table><h2 id="面试题速查" tabindex="-1">面试题速查 <a class="header-anchor" href="#面试题速查" aria-label="Permalink to &quot;面试题速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>一句话答案</th></tr></thead><tbody><tr><td>CAP 是什么</td><td>一致性/可用性/分区容错三选二；分区必选，实际是一致性与可用性二选一</td></tr><tr><td>CP 和 AP 例子</td><td>ZooKeeper=CP；Eureka=AP；业务系统=AP+最终一致</td></tr><tr><td>BASE 是什么</td><td>基本可用 + 软状态 + 最终一致</td></tr><tr><td>分布式事务方案</td><td>2PC（阻塞）/ TCC（侵入大）/ 本地消息表（常用）/ Saga（无隔离）</td></tr><tr><td>雪花算法</td><td>时间戳+机器ID+序列号，趋势递增，防时钟回拨</td></tr><tr><td>一致性哈希</td><td>环映射 + 虚拟节点，节点变动影响最小化</td></tr></tbody></table><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/knowledge/service/mq-intro.html">消息队列（Kafka）入门</a> - 最终一致的载体</li><li><a href="/knowledge/service/spring-cloud.html">Spring Cloud 微服务</a> - 分布式组件落地</li><li><a href="/knowledge/service/redis-intro.html">Redis 入门</a> - 分布式锁、缓存一致性</li></ul>`,31)])])}const g=a(s,[["render",o]]);export{b as __pageData,g as default};
